import type { CharacterId, FxKind, Language } from '../../types'

// Who you can pick, what they wear, how they celebrate. The pixels live in art.ts
// (generated by tools/draw_art.py) and the sounds in assets/sfx/<id>/.
// To add a character: draw it in tools/draw_art.py, add an entry here, add its
// id to CharacterId in types/index.d.ts and its voice to tools/make_sfx.py.

export type Text = Readonly<Record<Language, string>>
export type Slot = 'eyes' | 'mouth' | 'head' | 'hat' | 'hand' | 'stage'
export type Item = { id: string; slot: Slot; price: number; level: number; name: Text }

export type Character = {
  id: CharacterId
  name: string
  // The pane's accent colour.
  color: string
  blurb: Text
  hello: Text
  // `twinkle`: four-point stars; `note`: little music notes that float up.
  sparkle: 'twinkle' | 'note'
  fxColors: Readonly<Record<FxKind, readonly string[]>>
  // While happy, how many pixels the hat and the ears rise on each tick (cycled).
  happy: { hat: readonly number[]; ears: readonly number[] }
  items: readonly Item[]
}

