export function characterOf(id: CharacterId | null | undefined): Character {
  return CHARACTERS.find(one => one.id === id) ?? CHARACTERS[0]!
}

export function isCharacterId(value: unknown): value is CharacterId {
  return CHARACTERS.some(one => one.id === value)
}

// `locki/aviators` → the character and the item.
export function itemOf(fullId: string): { character: Character; item: Item } | undefined {
  const [owner, id] = fullId.split('/')
  const character = CHARACTERS.find(one => one.id === owner)
  const item = character?.items.find(one => one.id === id)

  return character !== undefined && item !== undefined ? { character, item } : undefined
}

export function fullId(character: CharacterId, item: string): string {
  return `${character}/${item}`
}
